import {assertionSchema} from './assertions.js';
// Full JSON Schema (2020-12) for every core operation, with examples that apply on a fixture. One source for
// `ops.apply` validation, `operations.list/describe` and MCP `mai://operation/{type}` (plan F0). The core still
// validates semantics inline (existence, topology, identity); these schemas make the fields discoverable so an agent
// never has to guess them. tests/operations-schema.test.ts keeps this in sync with OPERATION_TYPES.
import {PROPERTIES,type Operation,type Property} from './model.js';
import {starterSvg} from './document.js';

export type Schema={[key:string]:unknown};
export type OperationType=Operation['type'];
export type Family='scene'|'path'|'timeline'|'rig'|'identity'|'semantic'|'params'|'expression'|'modifiers'|'secondary'|'character'|'components'|'state-machine'|'filters'|'morph';
export type OperationDoc={family:Family;summary:string;schema:Schema;examples:{why:string;op:Operation;setup?:Operation[];fixture?:FixtureName}[];
 /** Macros expand into other operations: the agent can inspect and edit the result instead of treating it as a black box. */
 expands?:string};
export type FixtureName='starter'|'alpha';
export const FIXTURES:Record<FixtureName,string>={starter:starterSvg,
 alpha:'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100" mask="url(#mai-alpha)"><defs><mask id="mai-alpha" maskUnits="userSpaceOnUse" x="0" y="0" width="100" height="100"><path d="M0 0H100V100H0Z" fill="white" opacity="0.5"/></mask></defs><path id="shape" d="M10 10L30 10L30 30L10 30Z" fill="#ff0000"/><path id="shape-2" d="M40 10L60 10L60 30L40 30Z" fill="#00ff00"/></svg>'};

