/** Schema for one operation (closed object with its `type` const). */
export function operationSchema(type:OperationType):Schema{const d=OPERATION_DOCS[type];const props=d.schema.properties as Record<string,Schema>;return {title:type,description:d.summary,...d.schema,properties:{...props,type:{const:type}}};}
/** Discriminated union of every operation: what `ops.apply` validates. */
export function operationUnionSchema():Schema{const types=Object.keys(OPERATION_DOCS) as OperationType[];
 return {description:'Core operation, discriminated by `type`. Use operations.describe {type} for fields, examples and identity impact.',type:'object',required:['type'],properties:{type:{type:'string',enum:types}},
  allOf:types.map(t=>({if:{properties:{type:{const:t}},required:['type']},then:operationSchema(t)}))};}
